const POSL=t=>t?t.charAt(0).toUpperCase()+t.slice(1):"";
const HISTH=f=>f.city?"Historie města":/^(Biskupství|Arcibiskupství|Papežská|Duchovenstvo)/.test(f.name)?"Historie":"Historie rodu";
const HIST=[];
function setSel(id,push=true,city=null){
  if(push&&st.sel&&(st.sel!==id||st.city!==city)){HIST.push({id:st.sel,city:st.city});if(HIST.length>30)HIST.shift()}
  st.sel=id; st.city=id?city:null; st.focus=null;
  document.getElementById("famsel").value=st.sel||"";
  if(st.sel&&byId[st.sel].nbr&&typeof setTab==="function")setTab(byId[st.sel].land);
  document.getElementById("ringlegend").hidden=!st.rings||!st.sel||!relsFor(st.sel).length;
  drawMap(); renderDetail();
}
function select(id){setSel(st.sel===id&&!st.city?null:id)}
function show(id){setSel(id)}
function showCity(id,name){setSel(id,true,name)}
function goBack(){const h=HIST.pop();if(h)setSel(h.id,false,h.city)}
const histName=h=>h.city||byId[h.id].name;

/* cards */
const fs=document.getElementById("famsel");
const _nrm=s=>String(s).normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();
function buildCards(container,lands,nbr){
  if(!FAM.some(f=>!!f.nbr===nbr)){container.innerHTML=`<div class="placeholder"><p>Družina zatím nezná žádný ${nbr?"sousední ":""}rod. Přibudou, jak o nich uslyší nebo je potká.</p></div>`;return}
  for(const L of lands){
    const fams=FAM.filter(f=>f.land===L&&!!f.nbr===nbr); if(!fams.length)continue;
    const sec=document.createElement("div"); sec.className="land-sec"; sec.dataset.land=L;
    sec.innerHTML=`<h3 class="landh">${L.toUpperCase()}</h3>`;
    const grid=document.createElement("div"); grid.className="cards";
    const og=document.createElement("optgroup"); og.label=nbr?`Soused: ${L}`:L;
    for(const f of fams){
      const c=document.createElement("article"); c.className="card"; c.dataset.id=f.id; c.dataset.fc=f.conf; c.dataset.fl=f.land;
      c.dataset.txt=_nrm(f.name+" "+f.head+" "+f.seats.map(s=>s[0]).join(" ")+" "+f.stance);
      c.innerHTML=`<span class="cseal f-${f.conf}" title="${CONFN[f.conf]}"><img src="${FICON[f.conf]}" alt="${CONFN[f.conf]}"></span><div class="cimg">${ARMS[f.id]?armsImg(f,"armcard"):shield0(f).replace('class="shield"','class="cshield"')}</div>
        <div class="cbody"><h3>${f.name}</h3>
        <p class="head">${f.head}</p>
        ${f.seats.length?`<p class="seats">${f.seats.map(s=>s[0]).join(" · ")}</p>`:""}</div>`;
      c.tabIndex=0; c.setAttribute("role","link"); c.setAttribute("aria-label",f.name);
      {const go=()=>navTo("#rod/"+f.id);
       c.addEventListener("click",go); c.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();go()}});}
      if(!f.nomap){const o=document.createElement("option"); o.value=f.id; o.textContent=f.name; og.appendChild(o);}
      grid.appendChild(c);
    }
    sec.appendChild(grid); container.appendChild(sec); if(og.children.length)fs.appendChild(og);
  }
}
buildCards(document.getElementById("cardlands"),["Čechy","Morava","Slezsko","Lužice","Královská města","Duchovenstvo"],false);
/* desky: filters + list view */
const DF={conf:"all",land:"all",q:"",view:"cards"};
