/* clicking a holding in the detail panel centres the map on it */
document.addEventListener("click",e=>{
  const b=e.target.closest(".plink"); if(!b)return;
  const f=byId[st.sel]; if(!f)return;
  const sd=f.seats.find(x=>x[0]===b.dataset.place); if(!sd)return;
  st.focus=sd[0];
  const [x,y]=P(sd[1],sd[2]); mapCenter(x,y,230); renderDetail();
  const m=document.getElementById("map").getBoundingClientRect();
  if(m.bottom<0||m.top>innerHeight*0.6)document.getElementById("map").scrollIntoView({behavior:matchMedia("(prefers-reduced-motion:reduce)").matches?"auto":"smooth",block:"center"});
});

/* clicking a house name anywhere shows its holdings on the map */
document.addEventListener("click",e=>{
  const b=e.target.closest(".flink"); if(!b)return;
  const id=b.dataset.id,f=byId[id];
  if(b.closest("#detail")&&!f.nomap){show(id);return}
  navTo("#rod/"+id);
});

if(matchMedia("(max-width:700px)").matches)document.querySelectorAll("details.fold").forEach(d=>{d.open=false});

/* zoom & pan: wheel, mouse drag, two-finger pinch; full redraw after the gesture settles */
const mapDrag={moved:false};
(function(){
  const pts=new Map(); let last=null, drawT=null;
  const curVB=()=>st.vb||VB[st.zoom];
  const clampVB=v=>{let [x,y,w,h]=v;w=Math.min(680,Math.max(80,w));h=w*605/680;x=Math.max(-40,Math.min(720-w,x));y=Math.max(-40,Math.min(645-h,y));return [x,y,w,h]};
  function setVB(v){st.vb=clampVB(v);svg.setAttribute("viewBox",st.vb.join(" "));clearTimeout(drawT);drawT=setTimeout(drawMap,180)}
  function toUser(cx,cy){const r=svg.getBoundingClientRect(),v=curVB();return [v[0]+(cx-r.left)/r.width*v[2],v[1]+(cy-r.top)/r.height*v[3]]}
  function zoomAt(f,ux,uy){const v=curVB(),w=v[2]*f,h=w*605/680;setVB([ux-(ux-v[0])*w/v[2],uy-(uy-v[1])*h/v[3],w,h])}
  window.mapZoom=(f)=>{const v=curVB();zoomAt(f,v[0]+v[2]/2,v[1]+v[3]/2)};
  window.mapCenter=(x,y,maxW)=>{const v=curVB(),w=Math.min(v[2],maxW),h=w*605/680;st.vb=clampVB([x-w/2,y-h/2,w,h]);clearTimeout(drawT);drawMap()};
  svg.addEventListener("wheel",e=>{e.preventDefault();const [ux,uy]=toUser(e.clientX,e.clientY);zoomAt(e.deltaY>0?1.15:1/1.15,ux,uy)},{passive:false});
  svg.addEventListener("pointerdown",e=>{pts.set(e.pointerId,[e.clientX,e.clientY]);mapDrag.moved=false;last=null});
  svg.addEventListener("pointermove",e=>{
    if(!pts.has(e.pointerId))return;
    const prev=pts.get(e.pointerId); pts.set(e.pointerId,[e.clientX,e.clientY]);
    const r=svg.getBoundingClientRect(),v=curVB();
    if(pts.size===1&&e.pointerType==="mouse"&&e.buttons===1){
      const dx=(e.clientX-prev[0])/r.width*v[2],dy=(e.clientY-prev[1])/r.height*v[3];
      if(Math.abs(e.clientX-prev[0])+Math.abs(e.clientY-prev[1])>0){mapDrag.moved=mapDrag.moved||Math.hypot(e.clientX-prev[0],e.clientY-prev[1])>2;if(mapDrag.moved){svg.setPointerCapture(e.pointerId);setVB([v[0]-dx,v[1]-dy,v[2],v[3]])}}
    }else if(pts.size===2){
      const [a,b]=[...pts.values()],d=Math.hypot(a[0]-b[0],a[1]-b[1]),mx=(a[0]+b[0])/2,my=(a[1]+b[1])/2;
      if(last){const [ux,uy]=toUser(mx,my);const f=last.d/d;const pv=curVB();const panx=(last.mx-mx)/r.width*pv[2],pany=(last.my-my)/r.height*pv[3];zoomAt(f,ux,uy);const nv=curVB();setVB([nv[0]+panx,nv[1]+pany,nv[2],nv[3]]);mapDrag.moved=true}
      last={d,mx,my};
    }
  });
  const end=e=>{pts.delete(e.pointerId);if(pts.size<2)last=null;setTimeout(()=>{if(!pts.size)mapDrag.moved=false},0)};
  svg.addEventListener("pointerup",end);svg.addEventListener("pointercancel",end);
})();
document.getElementById("zin").addEventListener("click",()=>mapZoom(1/1.4));
document.getElementById("zout").addEventListener("click",()=>mapZoom(1.4));

const BVLZ={"Drtivá":"Ignoruje Resistance zbroje proti Bludgeoning.","Průrazná":"Ignoruje Resistance zbroje proti Piercing.","Šikovná":"Před hodem na útok si útočník zvolí typ zranění podle zbraně.",
  "Ostrá":"Při Slashing proti cíli bez Resistance je kritický zásah už na 19–20.","Půlmeč":"Bonusovou akcí přehmat zbraně: Piercing útoky získají vlastnost Průrazná, kostka zranění klesne o stupeň (d8 na d6).",
  "Ratiště":"Když nepřítel vstoupí do dosahu zbraně (10 stop), smí udělat Opportunity Attack. V kontaktu (5 stop) má na útoky nevýhodu.",
  "Do slabin!":"Padne-li proti Restrained nebo Prone cíli Požehnání, jde o automatický kritický zásah.","Strhující":"Padne-li při útoku na jezdce Požehnání, může ho strhnout (cíl hází záchranu, zda bude Prone, nebo jen stržen z koně).",
  "Vpřed!":"Po jízdě aspoň 15 stop rovně se zdvojnásobí kostky zranění (kritický zásah 4×).","Štěpící":"Padne-li při útoku na cíl se štítem Požehnání, může štít zničit.",
  "Hrom a kouř!":"Pokušení: zbraň selže a před dalším užitím potřebuje opravu. Požehnání: střelce zahalí dým a má výhodu proti útokům zblízka."};
const BZBR={"Vycpávaná":["Bludgeoning","1×"],"Kroužková":["Bludgeoning, Slashing","2×"],"Plátová":["Slashing, Piercing","3×"],"Komplexní":["Bludgeoning, Slashing, Piercing","3×"],"Štít":["—","1×"]};
/* malované ikony vlastností zbraní (zv-), typů zranění (zr-) a zbrojí (zb-) – art/img/boj, zadání vyvoj/ikony-boj.md */
const BZVK={"Drtivá":"drtiva","Průrazná":"prurazna","Šikovná":"sikovna","Ostrá":"ostra","Půlmeč":"pulmec","Do slabin!":"do-slabin","Ratiště":"ratiste","Strhující":"strhujici","Vpřed!":"vpred","Štěpící":"stepici","Hrom a kouř!":"hrom-a-kour"};
const BZRT={Bludgeoning:"Drtivé",Piercing:"Bodné",Slashing:"Sečné",Fire:"Ohnivé",Cold:"Mrazivé",Lightning:"Bleskové",Thunder:"Hromové",Acid:"Kyselinové",Poison:"Jedové",Necrotic:"Prokleté",Radiant:"Svaté",Psychic:"Psychické",Force:"Silové"};
const BZBK={"Vycpávaná":"vycpavana","Kroužková":"krouzkova","Plátová":"platova","Komplexní":"komplexni","Štít":"stit"};
const bikE=t=>String(t).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const bik=(f,tip,c)=>`<img class="bi bimg bik${c?" "+c:""}" src="art/img/boj/${f}-48.webp" srcset="art/img/boj/${f}-48.webp 48w, art/img/boj/${f}-96.webp 96w" sizes="24px" width="24" height="24" alt="${bikE(tip)}" aria-label="${bikE(tip)}" data-tip="${bikE(tip)}" decoding="async" loading="lazy">`;
const bikZvTip=k=>`${k} (vlastnost zbraně): ${BVLZ[k]}`;
const bikZv=k=>BZVK[k]?bik("zv-"+BZVK[k],`${k} (vlastnost zbraně): ${BVLZ[k]}`,"bik-zv"):"";
const bikZrTip=t=>t==="magicke"?"Magické zranění – Resistance a Immunity vůči nemagickým útokům na ně neplatí":t==="stribrne"?"Stříbrné zranění (silvered) – překoná ochranu, kterou má jen obyčejná zbraň":`${BZRT[t]} (${t})`;
const bikZr=t=>BZRT[t]?bik("zr-"+t.toLowerCase(),bikZrTip(t),"bik-zr"):t==="magicke"||t==="stribrne"?bik("zr-"+t,bikZrTip(t),"bik-zr bik-zr2"):"";
const bikZbTip=k=>{const z=BZBR[k];return k==="Štít"?"Štít · bez Resistance · vydrží 1× (obětování při kritickém zásahu)":`${k} zbroj · Resistance ${z[0]} · vydrží ${z[1]} (obětování při kritickém zásahu)`};
const bikZb=k=>BZBK[k]?bik("zb-"+BZBK[k],bikZbTip(k),"bik-zb"):"";
/* zbroj i s medailonky typů zranění, proti kterým dává Resistance */
const bikZbR=k=>!BZBK[k]?"":`<span class="bikzb">${bikZb(k)}${BZBR[k][0]==="—"?"":BZBR[k][0].split(/,\s*/).map(bikZr).join("")}</span>`;
/* typy zranění v textu („Slashing nebo Piercing“, „Svaté (Radiant)“) jako řada medailonků */
const bikZrTxt=t=>{const r=[],x=String(t||"");x.replace(/\b(Bludgeoning|Piercing|Slashing|Fire|Cold|Lightning|Thunder|Acid|Poison|Necrotic|Radiant|Psychic|Force)\b/g,(m,a)=>{if(!r.includes(a))r.push(a);return m});
  if(!/\b(Necrotic)\b/.test(x)&&/prokleté/i.test(x))r.push("Necrotic");if(!/\bRadiant\b/.test(x)&&/(^|\s)svaté/i.test(x))r.push("Radiant");
  const o=r.map(bikZr);if(/stříbrn|silvered/i.test(x))o.push(bikZr("stribrne"));if(/magick|magical/i.test(x))o.push(bikZr("magicke"));return o.join("")};
/* vlastnosti zbraní v textu („dosah 10 stop, Průrazná“) */
const bikZvTxt=t=>Object.keys(BZVK).filter(k=>new RegExp(`(?<![\\p{L}])${k.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}(?![\\p{L}])`,"u").test(String(t||""))).map(bikZv).join("");
/* druhy zbroje z popisu AC („kroužková košile, štít“, „kyrys a pavéza“, „plná zbroj“) */
const bikZbDruhy=t=>{t=String(t||"").toLowerCase();if(/kouzeln|přirozen|mage armor|zbytky/.test(t)&&!/štít|pavéz/.test(t))return [];const d=[];
  if(/plná zbroj|komplexn|\bplate\b/.test(t))d.push("Komplexní");else if(/plátov|kyrys|brigantin|půlplát|breastplate|half-plate|splint/.test(t))d.push("Plátová");
  else if(/kroužkov|drátěn|šupin|chain|scale|ring mail/.test(t))d.push("Kroužková");else if(/kožen|prošívan|vycpávan|gambeson|padded|leather|hide/.test(t))d.push("Vycpávaná");
  if(/štít|pavéz|shield/.test(t))d.push("Štít");return d};

